import { Switch, Route, Redirect } from "react-router-dom";
import Signup from "./componant/signup";
import Login from "./componant/login";

function App() {
    return (
        <Switch>
            <Route exact path="/">
                <Redirect to="/signup" />
            </Route>
            <Route path="/signup" component={Signup} />
            <Route path="/login" component={Login} />
        </Switch>
    );
}
